        banksel PORTA
; OUTPUT PORTB.0
        banksel TRISB
        bcf     TRISB, 0
        banksel PORTA
        movlw   0x01
        movwf   v_i
        movlw   0x0A
        movwf   for2_to            ; loop limit
for_0
        movf    v_i, w
        subwf   for2_to, w         ; to - var
