        movf    tmp0, w
        subwf   tmp1, w            ; rhs - lhs
        movlw   0x00
        btfss   STATUS, C
        movlw   0x01               ; > true
        iorlw   0x00               ; test condition
        btfsc   STATUS, Z
        goto    else_3
        banksel PORTA
        bsf     PORTB, 0           ; HIGH RB0
        goto    endif_2
else_3
        banksel PORTA
        bcf     PORTB, 0           ; LOW RB0
endif_2
; DELAY 100ms (~100000 cycles @ 4000kHz)
        movlw   0xB7
        movwf   rt_d1
dl4_1
        movlw   0xB6
        movwf   rt_d0
dl4_0
        decfsz  rt_d0, f
        goto    dl4_0
        decfsz  rt_d1, f
        goto    dl4_1
        incf    v_i, f             ; var++
        goto    for_0
next_1
; END
end_5
        goto    end_5

; end of program: trap here
__halt
        goto    __halt

; FUNCTION square
sub_square
        movf    p_square_x, w      ; load x
        movwf   tmp0               ; save lhs
        movf    p_square_x, w      ; load x
        movwf   rt_b               ; rhs
        movf    tmp0, w
        movwf   rt_a               ; lhs
        call    _mul8
        return  
        return  

; ==================== runtime support ====================

; 8x8 multiply (low byte): W = rt_a * rt_b
_mul8
        clrf    rt_res
        movf    rt_b, w
        movwf   rt_cnt
_mul8_loop
